import json

# Claim under test: wearing less on cold, overcast days causes arthritis.
# A option "questions" the claim most when it gives a direct case where the
# exposure (wearing less in such weather) is present, the outcome (arthritis)
# is absent, and the comparison is close to the claimant's own situation.

options = {
    "A": {"exposure_present": True, "outcome_absent": True, "same_context": False, "same_population": False},
    "B": {"exposure_present": True, "outcome_absent": False, "same_context": False, "same_population": False},
    "C": {"exposure_present": True, "outcome_absent": True, "same_context": True, "same_population": True},
    "D": {"exposure_present": False, "outcome_absent": False, "same_context": False, "same_population": False},
}

def score(o):
    # Direct counterexample to causation requires exposure without outcome.
    base = 1 if (o["exposure_present"] and o["outcome_absent"]) else 0
    # Closeness to the claimant's own circumstances strengthens the challenge.
    return base * (1 + o["same_context"] + o["same_population"])

scores = {k: score(v) for k, v in options.items()}
best = max(scores, key=lambda k: (scores[k], k == "C"))

result = {
    "final_answer": best,
    "evidence": {
        "scores": scores,
        "rule": "exposure present and outcome absent, weighted by same context and population",
    },
}

print(json.dumps(result, separators=(",", ":")))
